import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1793788774000}`),a={name:`guide/faq.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Something narrowed the list. In order of likelihood:</p><ul><li><code>IMAP_READ_ONLY</code> is set, and it is a write tool.</li><li><code>IMAP_ALLOW_TOOLS</code> is set and does not name it — it is an allow list, so anything not named is out.</li><li><code>IMAP_DENY_TOOLS</code> names it, possibly through a prefix such as <code>delete_*</code>.</li></ul><p>A filtered tool is not registered at all, so it is missing from <code>tools/list</code> and answers <code>tools/call</code> with &quot;tool not found&quot; — the same as a write tool under read-only. There is no state where it is hidden but still callable.</p><p>What it is <em>not</em> is a typo in one of those variables: an entry that matches no tool stops the server at startup and says which entry it was. See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><h2 id="a-search-fails-with-timed-out-after-30-seconds" tabindex="-1">A search fails with &quot;timed out after 30 seconds&quot; <a class="header-anchor" href="#a-search-fails-with-timed-out-after-30-seconds" aria-label="Permalink to “A search fails with &quot;timed out after 30 seconds&quot;”">​</a></h2><p>The mail server took longer than this server gives one IMAP command. If it is slow rather than unreachable — a <code>body</code> search over a large folder is the usual case — raise <code>IMAP_COMMAND_TIMEOUT_SECONDS</code>, and check your client&#39;s own deadline first; see <a href="/guide/configuration#slow-servers">slow servers</a>. If even a small folder times out, the server is not answering, and more time will not help.</p><h2 id="a-call-fails-with-mailbox-busy" tabindex="-1">A call fails with <code>MAILBOX_BUSY</code> <a class="header-anchor" href="#a-call-fails-with-mailbox-busy" aria-label="Permalink to “A call fails with MAILBOX_BUSY”">​</a></h2><p>Another call was using the same mailbox for longer than <code>IMAP_COMMAND_TIMEOUT_SECONDS</code> allows, so this one gave up before sending anything — trying again is safe. If it keeps happening, a slow command such as a <code>body</code> search or a large download is holding the mailbox; see <a href="/guide/configuration#slow-servers">slow servers</a>.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};